package io.github.diodeme.ji.artifact;

import java.util.List;

/** Startup validation evidence for database-referenced artifacts. */
public record ArtifactValidationReport(List<Issue> issues) {
    public ArtifactValidationReport { issues = List.copyOf(issues); }
    public boolean valid() { return issues.isEmpty(); }
    public record Issue(ArtifactId artifactId, Kind kind) {}
    public enum Kind { MISSING, CORRUPT }
}
